"""Execute actual selector/validators/native relationship witness with explicit collaborators."""
from pathlib import Path
import json,re,subprocess,unittest
ROOT=Path(__file__).resolve().parents[2]
class FileParentFocused(unittest.TestCase):
 def php(self,code,case='good'):
  p=subprocess.run(['php','-r',code,str(ROOT),case],capture_output=True,text=True,timeout=10);self.assertEqual(p.returncode,0,p.stderr);self.assertEqual(p.stderr,'');return json.loads(p.stdout)
 def test_actual_driver_phase_selects_only_exact_new_phase(self):
  s=(ROOT/'support/governance/native-organization/test-native-organization-mysql.php').read_text();block=s[s.index('$arguments='):s.index('$workbench_http=')]
  for args,wanted in [(['--file-parent-policy'],'file-parent-policy'),(['--file-parent-policy','--file-source-facts'],'invalid'),(['--file-parent-policy=1'],'invalid'),(['--file-parent-policy','--file-parent-policy'],'invalid')]:
   self.assertEqual(self.php('$argv=array_merge(["driver"],json_decode($argv[2],true));'+block+'echo json_encode($phase);',json.dumps(args)),wanted)
  selected=s.split("}elseif($phase==='file-parent-policy'){",1)[1].split("}elseif(",1)[0]
  self.assertLess(selected.index('governance_completion_start_gorge'),selected.index('governance_recovery_file_parent_policy_focused'))
  self.assertIn("'gorge.file.uri'=>$file_service['uri']",selected);self.assertIn("'gorge.file.token'=>$file_service['token']",selected)
  self.assertIn("'native-File-parent-policy-endpoints'",s);self.assertIn("'owned-native-File-parent-policy-endpoints-no-permit'",s)
 def test_actual_six_case_obligations_and_result_tampering_rejected(self):
  code=r'''require $argv[1].'/support/governance/recovery/file-parent-policy-focused.php';$expected=governance_recovery_file_parent_policy_obligations();$records=array_fill_keys($expected,true);$r=['native_reader_relationships'=>['owned_User_RR_scope_observed'=>true,'same_server_observed'=>true,'File_reader_is_User_writer'=>false,'Task_reader_is_User_writer'=>false,'File_Task_same_physical_reader'=>false,'same_snapshot_proved'=>false]];$out=[];foreach(['good','missing','foreign','false','type','extra','snapshot','reader','null']as$case){$v=$records;$x=$r;if($case==='missing')array_pop($v);if($case==='foreign'){$keys=array_keys($v);unset($v[$keys[0]]);$v['foreign']=true;}if($case==='false')$v[$expected[0]]=false;if($case==='type')$v[$expected[0]]=1;if($case==='extra')$x['permit']=false;if($case==='snapshot')$x['native_reader_relationships']['same_snapshot_proved']=true;if($case==='reader')$x['native_reader_relationships']['File_reader_is_User_writer']=true;if($case==='null')$x=null;try{governance_recovery_file_parent_policy_validate_cases($v,$x);$out[]=true;}catch(RuntimeException$e){$out[]=false;}}echo json_encode(['labels'=>$expected,'out'=>$out]);'''
  d=self.php(code);self.assertEqual(d['out'],[True]+[False]*8)
  text=(ROOT/'support/governance/recovery/file-parent-policy-cases.php').read_text();labels=re.findall(r"'(file-parent-policy-[A-Za-z0-9-]+)'\);",text);self.assertEqual(len(labels),6);self.assertEqual(set(labels),set(d['labels']))
 def test_actual_reader_witness_observes_separate_endpoints_and_refuses_aliases(self):
  code=r'''require $argv[1].'/support/governance/recovery/file-parent-policy-cases.php';class AphrontMySQLiDatabaseConnection{function __construct(public$kind){}function isInsideTransaction(){return$GLOBALS['case']==='active'&&$this->kind==='file';}function isReadLocking(){return false;}function isWriteLocking(){return false;}}class PhabricatorUser{function establishConnection($mode){if($mode!=='w')throw new Exception('wrong mode');return new AphrontMySQLiDatabaseConnection('user');}}class PhabricatorFile{function establishConnection($mode){if($mode!=='r')throw new Exception('wrong mode');return new AphrontMySQLiDatabaseConnection('file');}}class ManiphestTask{function establishConnection($mode){if($mode!=='r')throw new Exception('wrong mode');return new AphrontMySQLiDatabaseConnection('task');}}class ScopeSeam{function getFacts(){$GLOBALS['scope_checks']++;}}function queryfx_one($conn,$sql){if($GLOBALS['case']==='error')throw$GLOBALS['original'];if($sql!=='SELECT CAST(CONNECTION_ID() AS CHAR) connection_id,@@server_uuid server_uuid,DATABASE() database_name')throw new Exception('unexpected query');$k=$conn->kind;$id=['user'=>'1','file'=>'2','task'=>'3'][$k];if($GLOBALS['case']==='alias')$id='1';$row=['connection_id'=>$id,'server_uuid'=>str_repeat('a',36),'database_name'=>'governance_native_'.str_repeat('a',16).['_user','_file','_maniphest'][array_search($k,['user','file','task'],true)]];if($GLOBALS['case']==='replica'&&$k==='file')$row['server_uuid']=str_repeat('b',36);if($GLOBALS['case']==='foreign'&&$k==='task')$row['database_name']='foreign';if($GLOBALS['case']==='malformed')$row['connection_id']='bad';return$row;}$GLOBALS['case']=$argv[2];$GLOBALS['scope_checks']=0;$GLOBALS['original']=new RuntimeException('original-SQL-error');$facts=null;$error=null;$same=false;try{$facts=governance_recovery_file_parent_policy_reader_relationships(new ScopeSeam());}catch(Throwable$e){$error=$e->getMessage();$same=$e===$GLOBALS['original'];}echo json_encode(['facts'=>$facts,'error'=>$error,'original'=>$same,'checks'=>$GLOBALS['scope_checks'],'SQL_executed'=>false]);'''
  d=self.php(code);self.assertIsNone(d['error']);self.assertEqual(d['checks'],2);self.assertFalse(d['SQL_executed']);self.assertFalse(d['facts']['same_snapshot_proved']);self.assertFalse(d['facts']['File_reader_is_User_writer'])
  for case in ('active','alias','replica','foreign','malformed','error'):
   d=self.php(code,case);self.assertIsNone(d['facts']);self.assertIsNotNone(d['error']);self.assertEqual(d['original'],case=='error')
 def test_all_six_real_cases_are_called_by_new_focused_entry_and_observer_cleanup_retained(self):
  s=(ROOT/'support/governance/recovery/file-parent-policy-focused.php').read_text()
  for item in ('governance_recovery_file_source_prepare($fixture)','governance_recovery_file_parent_policy_cases($fixture,$observer,$state,$record)','governance_recovery_file_parent_policy_validate_cases($executed,$result)','information_schema.PROCESSLIST','governance_recovery_project_fixture_cleanup'):
   self.assertIn(item,s)
  self.assertNotIn('governance_recovery_file_source_native_cases(',s);self.assertNotIn('governance_recovery_file_source_raw_cases(',s)
 def test_actual_entry_real_producer_rejects_missing_file_before_any_native_prepare(self):
  code=r'''putenv('PHORGE_GOVERNANCE_GORGE_FILE_BINARY');putenv('PHORGE_GOVERNANCE_GORGE_FILE_SHA256');class PhorgeGovernanceCompletionFixture{function assertOwned(){$GLOBALS['owned']++;}}function governance_recovery_file_parent_policy_focused(...$args){$GLOBALS['prepared']=true;throw new Exception('unexpected prepare');}$s=file_get_contents($argv[1].'/support/governance/native-organization/test-native-organization-mysql.php');$start=strpos($s,"}elseif($"."phase==='file-parent-policy'){")+strlen("}elseif($"."phase==='file-parent-policy'){");$end=strpos($s,"}elseif(",$start);$body=substr($s,$start,$end-$start);$body=str_replace('__DIR__',var_export($argv[1].'/support/governance/native-organization',true),$body);$GLOBALS['owned']=0;$GLOBALS['prepared']=false;$fixture=new PhorgeGovernanceCompletionFixture();$check=static function(){throw new Exception('unexpected ready');};$reason=null;try{eval($body);}catch(RuntimeException$e){$reason=$e->getMessage();}echo json_encode(['reason'=>$reason,'owned'=>$GLOBALS['owned'],'native_prepare_executed'=>$GLOBALS['prepared'],'SQL_executed'=>false]);'''
  self.assertEqual(self.php(code),{'reason':'completion_paired_gorge_binary_required','owned':1,'native_prepare_executed':False,'SQL_executed':False})
